] as const;

export const UNAVAILABLE_MODULE_IDS = [
  'apifn',
  'botfn',
  'docsfn',
  'hostfn',
  'langfn',
  'userfn',
] as const;

export const NESTED_MODULE_IDS = ['catchfn', 'logfn'] as const;
export const FOLDED_MODULE_IDS = ['contentfn'] as const;

export const KNOWN_MODULE_IDS = [
  'apifn',
  'authfn',
  'billfn',
  'botfn',
  'browsefn',
  'cachefn',
  'catchfn',
  'cifn',
